//! Critical point comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_critical.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::Cubic;
use thermopack_rs::CubicKind;

const ATOL: [f64; 3] = [1.0e-6, 1.0e-12, 1.0e-3];
const RTOL: f64 = 1.0e-6;

#[test]
fn critical_points_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/critical.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let kind = match parts[0] {
            "SRK" => CubicKind::SoaveRedlichKwong,
            "RK" => CubicKind::RedlichKwong,
            "VDW" => CubicKind::VanDerWaals,
            _ => CubicKind::PengRobinson,
        };
        let components: Vec<&str> = parts[1].split(',').collect();
        let composition: Vec<f64> = parts[2].split(',').map(|v| v.parse().unwrap()).collect();
        let source: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        let model = Cubic::new(kind, &components).unwrap();
        let point = thermopack_rs::critical::critical_point(&model, &composition).unwrap();
        let native = [point.temperature, point.volume, point.pressure];
        for (position, (source, native)) in source.iter().zip(native.iter()).enumerate() {
            assert!(
                (source - native).abs() <= ATOL[position] + RTOL * source.abs(),
                "{case} {}: source {source} native {native}",
                ["temperature", "volume", "pressure"][position]
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 7);
}

#[test]
fn the_critical_point_is_an_inflection() {
    // The critical point is the state where the isotherm has an inflection,
    // so the first and the second volume derivative of the pressure vanish.
    let model = Cubic::new(CubicKind::PengRobinson, &["CO2"]).unwrap();
    let point = thermopack_rs::critical::critical_point(&model, &[1.0]).unwrap();
    let state = model.prepare(point.temperature, &[1.0]).unwrap();
    let pressure = state.pressure(point.volume).unwrap();
    assert!(pressure.dv.abs() < 1.0e-3, "{}", pressure.dv);
    assert!(
        state
            .pressure_second_derivative(point.volume)
            .unwrap()
            .abs()
            < 1.0e7
    );
}

#[test]
fn the_pseudo_critical_state_is_close() {
    // The pseudo critical state of the model is the initial guess of the
    // critical point, so the two agree to a few percent.
    let model = Cubic::new(CubicKind::PengRobinson, &["CO2"]).unwrap();
    let guess = model.pseudo_critical(&[1.0]).unwrap();
    let point = thermopack_rs::critical::critical_point(&model, &[1.0]).unwrap();
    assert!((point.temperature - guess.temperature).abs() < 0.1);
    assert!((point.volume - guess.volume).abs() / guess.volume < 1.0e-3);
}
